import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.AuRYXM_l.js";const u=JSON.parse('{"title":"Chainy design brief","description":"Version 0.2 · October 8, 2026 · Confirmed visual direction; production details proposed for team review.","frontmatter":{"title":"Chainy design brief","description":"Version 0.2 · October 8, 2026 · Confirmed visual direction; production details proposed for team review.","source":"docs/design/design-brief.md","category":"Game & system design","sourceUpdated":"2026-10-08T06:33:54+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/design/design-brief.md","filePath":"content/docs/design/design-brief.md"}'),r={name:"content/docs/design/design-brief.md"};function s(o,e,d,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-design-brief">Chainy design brief<a class="header-anchor" href="#chainy-design-brief" aria-label="Link to this section">​</a></h1><p>Version 0.2 · October 8, 2026 · Confirmed visual direction; production details proposed for team review.</p><p>This brief translates the <a href="/Chainy-Docs/content/docs/project-baseline.html">current decisions</a> and <a href="/Chainy-Docs/content/docs/game-design.html">game design document</a> into a small art, interface, and content production package. It specifies intended work, not completed assets or measured usability. Game assets and Unity prefabs belong in <a href="https://github.com/Kamiyon-Studio/Chainy-Game">Chainy-Game</a>; this repository holds their requirements and review records.</p><h2 id="direction-and-decision-status">Direction and decision status<a class="header-anchor" href="#direction-and-decision-status" aria-label="Link to this section">​</a></h2><p><strong>Confirmed:</strong> English first; ages 13–17; offline single-player Android; top-down 3D exploration; three educational levels across two thematic worlds; freely placed and configured technology components; blockchain synchronization, example-trained classification, and an agent challenge; badges and level progress as initial rewards. Touchscreen controls and Unity/C# are the technical direction.</p><p><strong>Confirmed visual direction (October 8):</strong> the user selected the first two Chainy storyboards as the definite style: cute, rounded toy-like 3D; the blue-haired explorer in yellow; friendly screen-faced robots; cubic island scenery; bright blue/green Blockchain World and violet AI World. Preserve these silhouettes, proportions, and friendly presentation. The 13–17 audience informs the reasoning, instructional copy, and challenge depth; it does not authorize replacing this art with realistic teenage characters. <a href="/Chainy-Docs/attachments/docs/media/gdd/reference-chainy-01.png">Reference sheet 1</a> and <a href="/Chainy-Docs/attachments/docs/media/gdd/reference-chainy-02.png">reference sheet 2</a> are the visual authority. Exact palette tokens, font licensing, model sources and final production assets still need specification.</p><p><strong>Gameplay reference only:</strong> the <a href="/Chainy-Docs/attachments/docs/media/gdd/reference-blockforge-gameplay.png">third BlockForge image</a> contributes records, linked blocks, ordering, tamper detection, verification, quizzes and node synchronization. Its flat drawing style, title, coins and certificate are not adopted design requirements. Storyboard counters and fixed answer slots do not override the three-level scope or free construction requirement.</p><p><strong>Recommended production approach:</strong> translate the confirmed style into a small reusable mobile asset kit, short practical missions and readable diagrams. A delivery-record setting, virtual stick, fixed top-down/isometric camera, 12-object construction cap, two initial classifier classes, and one short agent route remain implementation proposals. The <a href="/Chainy-Docs/content/docs/media/gdd/readme.html">GDD media register</a> distinguishes supplied references, generated concepts and runtime-ready assets.</p><p>The pre-final defense remains <strong>November 21, 2026</strong>. Prioritize comprehensible learning interactions over scenery quantity. CH-10 targets the reusable kit on October 25. The possible November 3–6 beta window at Tambunan National High School, Marinduque requires an integrated and checked build beforehand; follow the reconciled schedule in the planning documents. Preserve November integration, QA, pilot work, and rehearsal. Visual readiness cannot establish the school&#39;s undefined 60-percent completion requirement.</p><h2 id="visual-and-instructional-hierarchy">Visual and instructional hierarchy<a class="header-anchor" href="#visual-and-instructional-hierarchy" aria-label="Link to this section">​</a></h2><p>A player should identify the objective, the next available action, and the result of the last action without depending on narration. Use practical English and consistent words: record, link, validate, example, prediction, and policy. Introduce each term with the activity that demonstrates it.</p><p>Recommended visual hierarchy:</p><ol><li>The active objective and selected object stand out from decorative scenery.</li><li>Components show a stable icon and short label; selected components reveal their configuration and ports.</li><li>Validation marks the relevant object or connection and provides a short explanation plus a repair action.</li><li>Rewards confirm progress without implying certified mastery or interrupting correction.</li></ol><p>Use color together with shape, icons, labels, and connection patterns. A red line alone is insufficient to explain an invalid connection. Distinguish local replica agreement from internet connectivity; neither Wi-Fi imagery nor an online status indicator should imply a real network. Show classifier distance as distance, never as a confidence percentage. Label the agent&#39;s rule sequence and execution trace so it is not mistaken for generative AI.</p><h2 id="controls-and-small-screen-layout">Controls and small-screen layout<a class="header-anchor" href="#controls-and-small-screen-layout" aria-label="Link to this section">​</a></h2><p>The following are proposed interaction contracts to validate on the actual pilot phones.</p><table><thead><tr><th>Context</th><th>Input and layout</th><th>Required feedback and recovery</th></tr></thead><tbody><tr><td>Exploration</td><td>Left virtual stick; right context action; objective at top; pause away from action</td><td>Interactable objects receive a label; opening a modal stops movement input</td></tr><tr><td>Construction</td><td>Enter a dedicated mode; select palette part, preview position, confirm placement; tap to select and configure</td><td>Invalid placement explains the cause; cancel preview safely; allow move, remove, connect, disconnect, undo, and confirmed reset</td></tr><tr><td>Connections</td><td>Select source port, then compatible target; support tap selection without precision dragging</td><td>Highlight compatible targets; explain a rejected connection; make the selected source clear</td></tr><tr><td>Replica inspection</td><td>Three labeled replica summaries with an inspect panel</td><td>Show agreement/disagreement and the trusted reference; preview a repair before applying it</td></tr><tr><td>Classifier</td><td>Separate training examples and held-out test items; persistent Train and Test actions</td><td>Explain missing examples, ambiguous ties, wrong predictions, and changed training data</td></tr><tr><td>Agent</td><td>Rule list beside or below a compact route; Step, Run, Stop, Reset</td><td>Highlight current observation/action; show failure reason and bounded-stop state</td></tr><tr><td>Quiz</td><td>One prompt at a time; readable answer choices; explicit Submit</td><td>Disable repeated submission while saving; preserve the answer on failure; show explanation before Next</td></tr></tbody></table><p>Recommend landscape as the initial layout candidate, subject to device and user review; it is not a confirmed orientation requirement. Use safe-area-aware layouts, anchored panels, wrapping text, and scrollable explanations. Provide touch buttons as alternatives to small drag handles. Proposed minimum touch targets are approximately 48 logical display units with separation; Unity scaling must be checked on-device instead of treating canvas pixels as physical size. Text resizing must not hide actions or truncate essential instructions. Avoid gesture-only actions and audio-only information.</p><h2 id="screen-inventory-and-handoff">Screen inventory and handoff<a class="header-anchor" href="#screen-inventory-and-handoff" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Screen or surface</th><th>Essential content</th><th>Review acceptance</th></tr></thead><tbody><tr><td>Startup/recovery</td><td>Loading state and actionable content/storage failure</td><td>Preserve records; never show a false successful start</td></tr><tr><td>Learner profile</td><td>Study and learner code entry, local-profile confirmation, help</td><td>No password/account claim; warn when a valid code creates an empty local profile; no names in screenshots</td></tr><tr><td>Main menu/map</td><td>Continue, three level entries, progress, settings, separate staff entry</td><td>Locked activities explain the prerequisite; code entry on another device promises no restored progress</td></tr><tr><td>Mission briefing/HUD</td><td>One objective, short instructions, interaction prompt, pause</td><td>Instructions remain available; decorative text never obscures the task</td></tr><tr><td>Activity/workbench</td><td>Component palette, configuration, links, test, hint, undo/reset</td><td>At least two spatially different valid constructions are usable; reset needs confirmation</td></tr><tr><td>Feedback/quiz</td><td>Observed result, violated rule or explanation, next action</td><td>Errors remain retryable; first attempts are preserved by the data layer</td></tr><tr><td>Completion/progress</td><td>Earned badge, completed objective, return/continue</td><td>Completion appears only after the successful persistence response</td></tr><tr><td>Pause/settings</td><td>Resume, audio, text/readability, map, switch learner</td><td>Explain unsaved-edit behavior; switching profiles ends the current session</td></tr><tr><td>Staff export</td><td>Selected study/session scope, record count, destination action, package status</td><td>Cancellation and failed writes preserve data; saved file and confirmed receipt are visibly different states</td></tr></tbody></table><p>Staff entry is a workflow boundary, not verified authorization. An optional local PIN, if later adopted, must not be described as robust identity security. UI mockups should use synthetic learner codes and records only.</p><h2 id="bounded-level-dressing">Bounded level dressing<a class="header-anchor" href="#bounded-level-dressing" aria-label="Link to this section">​</a></h2><p>These quantities describe an initial production proposal, not approved extra content.</p><table><thead><tr><th>Level</th><th>Player goal and route</th><th>Reused scene/asset needs</th><th>Checkpoint boundary</th></tr></thead><tbody><tr><td>1: Records and links</td><td>Read brief → inspect delivery context → construct ordered records → verify → quiz</td><td>Shared ground/walls, small delivery props, one workbench, record blocks and link ports</td><td>Safe mission entry and committed activity/quiz progress</td></tr><tr><td>2: Verify and repair</td><td>Inspect changed record → compare reference → arrange three replicas → test disagreement and repair → quiz</td><td>Same workbench and record kit; three labeled node variants; reference/inspection panel</td><td>Last validated checkpoint; no partial repair shown as completed</td></tr><tr><td>3: Examples and decisions</td><td>Label examples → train/test → revise → configure and step delivery agent → quiz</td><td>Shared parcel variants, feature labels, compact route markers, obstacle, destination</td><td>Committed classifier/agent activity outcomes and quiz progress</td></tr></tbody></table><p>Provide obvious navigable paths and short sightlines to the next interaction. Do not add combat, extensive collectibles, cutscenes, inventory systems, or extra worlds as decoration requirements. Use one avatar and one reusable guide rig if a guide is needed; placeholder geometry is acceptable until the core loop is reviewed.</p><h2 id="asset-production-inventory">Asset production inventory<a class="header-anchor" href="#asset-production-inventory" aria-label="Link to this section">​</a></h2><p>The art lead maintains an asset register with ID, purpose, owner, source file, exported file, intended scene/prefab, license/provenance, version, and review status. Missing editable sources or usage rights block an asset&#39;s ready status.</p><table><thead><tr><th>Package</th><th>Proposed minimum</th><th>Delivery and import notes</th></tr></thead><tbody><tr><td>Environment</td><td>Ground/wall/path modules, workbench, small shared prop set</td><td>Editable source plus FBX; shared materials; simple colliders; align scale/pivots in the first integration sample</td></tr><tr><td>Actors</td><td>One avatar, optional shared guide, delivery agent</td><td>Reuse rigs/animations where possible; idle/move/interact only when needed by the loop</td></tr><tr><td>Learning components</td><td>Record block, node, connection/port, parcel and destination variants</td><td>Distinguishable at gameplay camera distance; stable labels; spatial layout must not encode a hidden correct solution</td></tr><tr><td>UI</td><td>Button/panel styles, component icons, status icons, progress/badge symbols</td><td>Editable vector/raster masters; PNG exports as needed; tested sprite bounds and nine-slice panels; avoid text baked into images</td></tr><tr><td>Fonts</td><td>One readable family with limited weights</td><td>Include license and English glyph coverage; verify fallback and enlarged text; no unverified font choice</td></tr><tr><td>Audio</td><td>Short interaction, valid result, error, completion sounds; optional loop</td><td>Editable/source WAV; compressed playback setting selected after device testing; no required voiceover or streaming</td></tr></tbody></table><p>Proposed model convention: 1 Unity unit represents 1 meter, environment pieces share an agreed grid, and placeable objects use predictable ground pivots. Confirm the first sample with the technical lead before bulk export. Use names such as <code>CH_Block_Record</code>, <code>CH_Node_Replica</code>, <code>CH_UI_QuizPanel</code>, and <code>CH_SFX_Validate</code>; distinguish source and runtime derivatives in the register.</p><p>Source art belongs in a separate editable-source folder in the game repository; Unity-ready assets go under <code>Assets/Chainy/Art</code> and <code>Assets/Chainy/Audio</code>, with UI prefabs under the agreed UI area. Commit Unity metadata with imported assets. Keep large unsupported source formats out of runtime resource folders. Third-party work must retain attribution/license text; generated assets still require provenance and visual review.</p><h2 id="proposed-resource-and-import-constraints">Proposed resource and import constraints<a class="header-anchor" href="#proposed-resource-and-import-constraints" aria-label="Link to this section">​</a></h2><p>Use the <a href="/Chainy-Docs/content/docs/hardware-validation.html">hardware validation plan</a> as the shared budget owner. Its 30 FPS, p95 frame time at most 40 ms, process memory at most 800 MiB, and APK at most 500 MB are <strong>proposed targets</strong>, not measured results. The candidate device class is 4 GB physical RAM; Android 11+ is provisional, with Android 10 subject to testing. No device list or performance certification is available.</p><p>Begin with simple shared materials, modest textures, inexpensive lighting, limited transparent effects, and simple collision. Proposed starting texture cap: 1024 pixels on the longest edge for ordinary assets, with smaller icons/props and documented exceptions for readability. This is an asset-production starting point, not a proven memory allocation. Choose compression with the pinned engine and tested devices; do not assume ASTC is universally available. Record texture dimensions, compression, mipmap choice, mesh complexity, material count, and audio import settings in the sample review before producing the full kit.</p><p>Bundle all required play content and audio. Show no first-run asset download or network dependency. Reduce props, texture sizes, particles, and shadow cost before weakening required learning interactions. Measure the combined scene on a phone; individual low-poly assets do not prove the whole scene meets its budget.</p><h2 id="parallel-production-and-review-contract">Parallel production and review contract<a class="header-anchor" href="#parallel-production-and-review-contract" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Work packet</th><th>Lead / support / reviewer</th><th>Owned output</th><th>Prerequisite and handoff evidence</th></tr></thead><tbody><tr><td>Asset sample and reusable kit, CH-10</td><td>Luis Cabrido III / Miguel De Leon / Christian Jude Villaber</td><td>Models, materials, audio register, isolated sample prefab/scene</td><td>CH-02 objectives and CH-03 import/render settings; sample screenshot plus on-device budget record before bulk production</td></tr><tr><td>Readable menus and HUD, CH-26</td><td>Miguel De Leon / Luis Cabrido III / Christian Jude Villaber</td><td>UI prefabs, state mockups, synthetic preview data</td><td>Frozen profile/mission/persistence interface; verify normal, invalid, loading, failure, and large-text states</td></tr><tr><td>Learning copy review</td><td>Sean Matthew Narvaez / Sherwin Limosnero / Christian Jude Villaber for simulator wording</td><td>Versioned instructions, hints, quiz explanations</td><td>GDD learning objectives and actual simulation behavior; flag misleading analogies or missing limitations</td></tr><tr><td>Scene integration, CH-13</td><td>Christian Jude Villaber / Luis Cabrido III and Miguel De Leon / Sherwin Limosnero</td><td>Integrated scene and build evidence</td><td>Reviewed component prefabs and stable content IDs; offline flow and device review</td></tr></tbody></table><p>These are proposed packet assignments consistent with named team roles; agent execution does not replace human review. Each agent gets a bounded folder or prefab and an agreed interface. Only the integration owner edits the shared scene, global style tokens, package settings, and input configuration in a given integration window. UI work uses synthetic state fixtures while gameplay and persistence are developed. Art and UI agents may work concurrently after the first sample contract; neither silently changes component IDs or content schemas. Resolve shared-file edits through the integrator.</p><p>A handoff includes the output paths, source/license record, import settings, screenshot or short capture, requirement IDs covered, known limitations, and the exact commit/build used. Acceptance evidence must be linked to the existing GitHub task; do not create duplicate tasks or call a card Done on visual polish alone.</p><h2 id="acceptance-and-unresolved-inputs">Acceptance and unresolved inputs<a class="header-anchor" href="#acceptance-and-unresolved-inputs" aria-label="Link to this section">​</a></h2><p>Review CH-R01, CH-R02, CH-R05–10 using a real target build: offline start; readable English instructions; reachable touch controls; clear construction editing; understandable agreement, classifier, and agent states; safe profile switching; persistence failures that preserve answers; and retryable export. Check enlarged text, device safe areas, long labels, sound disabled, invalid configurations, and interruption/relaunch. Visual sign-off requires the art/UI reviewers; educational clarity requires review against the GDD and subsequent actual learner evidence.</p><p>Still needed: representative phone models and resolutions within the retained specifications; confirmation of landscape orientation; production palette tokens and a licensed font; availability of editable licensed source assets/audio; approved component/content caps; per-person availability; and actual pilot feedback. The supplied Chainy style is confirmed. Runtime assets remain placeholders or reviewed kit derivatives until production and device validation are complete. These gaps do not justify inventing user-tested accessibility, measured performance, or approved research instruments.</p></div>',1)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
